import { redirect } from "next/navigation";
import { getCounselors, getLastGradeBumpYear, getStudents } from "@/lib/data";
import { createCounselorAccount, unlinkCounselorAccount, addCounselor, setCounselorAdmin, runGradeBumpNow } from "@/lib/actions";
import { getCurrentCounselor } from "@/lib/current-counselor";
import { Card, CardBody, CardHeader, CardTitle } from "@/components/ui/Card";
import { Pill } from "@/components/ui/Pill";
import { SubmitButton } from "@/components/ui/SubmitButton";
import { DeleteCounselorButton } from "@/components/settings/DeleteCounselorButton";

export const dynamic = "force-dynamic";

const inputClass =
  "w-full rounded-lg border border-navy-200 bg-white px-2.5 py-1.5 text-sm text-navy-900 focus:border-gold-400 focus:outline-none";
const labelClass = "mb-1 block text-xs font-medium text-navy-500";

export default async function CounselorSettingsPage() {
  // 계정/권한 관리는 관리자 카운슬러만 — 담당 학생 스코핑이 있는 일반 카운슬러는
  // 이 페이지에 접근할 수 없게 막아요.
  const actingCounselor = await getCurrentCounselor();
  if (!actingCounselor?.isAdmin) redirect("/");

  const [counselors, lastGradeBumpYear, students] = await Promise.all([
    getCounselors(),
    getLastGradeBumpYear(),
    getStudents(),
  ]);
  const assignedCountByCounselor = new Map<string, number>();
  for (const s of students) {
    if (!s.counselor_id) continue;
    assignedCountByCounselor.set(s.counselor_id, (assignedCountByCounselor.get(s.counselor_id) ?? 0) + 1);
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-serif text-2xl font-semibold text-navy-900">카운슬러 계정</h1>
        <p className="mt-1 text-sm text-navy-500">카운슬러 로그인 계정을 만들고 관리하세요. 로그인은 `/login`에서 해요.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>카운슬러 목록</CardTitle>
        </CardHeader>
        <CardBody className="space-y-3">
          {counselors.map((c) => (
            <div key={c.id} className="rounded-lg border border-navy-100 p-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div>
                  <span className="text-sm font-semibold text-navy-900">{c.name}</span>
                  <span className="ml-2 text-xs text-navy-400">{c.email ?? "이메일 없음"}</span>
                </div>
                <div className="flex items-center gap-1.5">
                  {c.is_admin && <Pill tone="gold">관리자</Pill>}
                  <Pill tone={c.auth_user_id ? "green" : "neutral"}>{c.auth_user_id ? "로그인 연결됨" : "미연결"}</Pill>
                  {(assignedCountByCounselor.get(c.id) ?? 0) > 0 && (
                    <Pill tone="neutral">담당 학생 {assignedCountByCounselor.get(c.id)}명</Pill>
                  )}
                </div>
              </div>

              {actingCounselor.id !== c.id && (
                <div className="mt-2 flex justify-end">
                  <form action={setCounselorAdmin.bind(null, c.id, !c.is_admin)}>
                    <SubmitButton
                      label={c.is_admin ? "관리자 권한 해제" : "관리자 권한 부여"}
                      variant={c.is_admin ? "ghost-danger-sm" : "secondary-sm"}
                      toastMessage={c.is_admin ? "관리자 권한이 해제되었습니다" : "관리자 권한이 부여되었습니다"}
                    />
                  </form>
                </div>
              )}

              {c.auth_user_id ? (
                <div className="mt-2 flex items-center justify-end gap-3">
                  {actingCounselor.id !== c.id && (
                    <DeleteCounselorButton
                      counselorId={c.id}
                      counselorName={c.name}
                      assignedStudentCount={assignedCountByCounselor.get(c.id) ?? 0}
                    />
                  )}
                  <form action={unlinkCounselorAccount.bind(null, c.id)}>
                    <SubmitButton label="로그인 연결 해제" variant="ghost-danger" toastMessage="해제되었습니다" />
                  </form>
                </div>
              ) : (
                <details className="mt-3">
                  <summary className="cursor-pointer list-none text-xs font-medium text-gold-600 hover:text-gold-700">
                    + 로그인 계정 만들기
                  </summary>
                  <form action={createCounselorAccount.bind(null, c.id)} className="mt-2 grid grid-cols-1 gap-3 border-t border-navy-100 pt-3 sm:grid-cols-3">
                    <div>
                      <label className={labelClass}>이메일 *</label>
                      <input type="email" name="email" required defaultValue={c.email ?? ""} className={inputClass} />
                    </div>
                    <div>
                      <label className={labelClass}>임시 비밀번호 *</label>
                      <input type="text" name="password" required minLength={6} className={inputClass} />
                    </div>
                    <div className="flex items-end">
                      <SubmitButton label="계정 생성" toastMessage="생성되었습니다" />
                    </div>
                  </form>
                </details>
              )}

              {!c.auth_user_id && actingCounselor.id !== c.id && (
                <div className="mt-2 flex justify-end">
                  <DeleteCounselorButton
                    counselorId={c.id}
                    counselorName={c.name}
                    assignedStudentCount={assignedCountByCounselor.get(c.id) ?? 0}
                  />
                </div>
              )}
            </div>
          ))}
        </CardBody>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>+ 새 카운슬러 추가</CardTitle>
        </CardHeader>
        <CardBody>
          <form action={addCounselor} className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            <div>
              <label className={labelClass}>이름 *</label>
              <input name="name" required className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>이메일</label>
              <input type="email" name="email" className={inputClass} />
            </div>
            <div className="flex items-end justify-between gap-3">
              <label className="flex items-center gap-2 pb-2 text-sm text-navy-700">
                <input type="checkbox" name="is_admin" />
                관리자 권한 부여
              </label>
              <SubmitButton label="추가" variant="secondary" toastMessage="추가되었습니다" />
            </div>
          </form>
        </CardBody>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>학년 자동 업데이트</CardTitle>
        </CardHeader>
        <CardBody className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <p className="text-sm text-navy-700">
              매년 9월 1일, 8~11학년 재학생 전원의 학년이 자동으로 한 학년씩 올라가요 (12학년은 그대로 두고, 졸업 처리는 따로 해주세요).
            </p>
            <p className="mt-1 text-xs text-navy-400">
              {lastGradeBumpYear ? `마지막 실행: ${lastGradeBumpYear}학년도` : "아직 실행된 적 없어요."}
            </p>
          </div>
          <form action={runGradeBumpNow}>
            <SubmitButton label="지금 실행" variant="secondary" toastMessage="실행되었습니다" />
          </form>
        </CardBody>
      </Card>
    </div>
  );
}
